#!/usr/bin/env node
/**
 * Installs pre-commit and pre-push Git hooks that run scripts/verify-tracked-imports.js
 * before any commit or push completes.
 */

const fs = require("fs");
const path = require("path");

const REPO_ROOT = path.resolve(__dirname, "..");
const HOOKS_DIR = path.join(REPO_ROOT, ".git", "hooks");

const HOOK_SCRIPT = `#!/bin/sh
# Auto-generated by scripts/install-git-hooks.js
REPO_DIR="$(cd "$(dirname "$0")/../.." && pwd)"
node "$REPO_DIR/scripts/verify-tracked-imports.js"
`;

if (fs.existsSync(HOOKS_DIR)) {
	for (const hookName of ["pre-commit", "pre-push"]) {
		const hookPath = path.join(HOOKS_DIR, hookName);
		fs.writeFileSync(hookPath, HOOK_SCRIPT, { mode: 0o755 });
		fs.chmodSync(hookPath, 0o755);
	}
	console.log("✅ Installed pre-commit and pre-push hooks in .git/hooks/");
}
